let timestamps = msg.payload.unix_seconds;
let prijzen = msg.payload.price;

let waarden = [];

// Loop door alle tijden (of het er nu 24 of 96 zijn)
for (let i = 0; i < timestamps.length; i++) {
    let datum = new Date(timestamps[i] * 1000);

    // .getTime() is iets veiliger in Javascript bij het rekenen met tijd
    let offset = datum.getTimezoneOffset() * 60000;
    let lokaleTijd = (new Date(datum.getTime() - offset)).toISOString().slice(0, 19).replace('T', ' ');

    waarden.push("('" + lokaleTijd + "', " + prijzen[i] + ")");
}

let sqlQuery = "INSERT OR REPLACE INTO epex_prijzen (tijdstip, prijs) VALUES " + waarden.join(", ") + ";";

msg.topic = sqlQuery;

// We gebruiken een eigen naam (msg.mijn_tekst) zodat SQLite het niet overschrijft!
msg.mijn_tekst = "✅ Succes! " + timestamps.length + " prijzen naar de database gestuurd.";

return msg;

// Vul hier jouw Telegram Chat ID in!
const mijnChatId = env.get("TELEGRAM_CHAT_ID"); 

// Jouw drempelwaarde
const drempel = 25;

let data = msg.payload;
if (typeof data === "string") {
    try { data = JSON.parse(data); } catch(e) {}
}

if (!data || !data.unix_seconds) {
    node.error("Fout: Geen prijzen gevonden.");
    return null;
}

let timestamps = data.unix_seconds;
let prijzen = data.price;

// 1. We halen de datum van morgen uit de allereerste tijdstempel
let datumMorgenObj = new Date(timestamps[0] * 1000);
let dag = String(datumMorgenObj.getDate()).padStart(2, '0');
let maand = String(datumMorgenObj.getMonth() + 1).padStart(2, '0');
let jaar = datumMorgenObj.getFullYear();
let weergaveDatum = dag + "-" + maand + "-" + jaar;

let blokken = [];
let inBlok = false;
let huidigeBlok = null;

// Loop door alle kwartieren om blokken te maken
for(let i=0; i < timestamps.length; i++) {
    let prijs = prijzen[i];

    if (prijs < drempel) {
        if (!inBlok) {
            inBlok = true;
            let startDatum = new Date(timestamps[i] * 1000);
            let offset = startDatum.getTimezoneOffset() * 60000;
            let startLokaleTijd = new Date(startDatum.getTime() - offset).toISOString().substring(11, 16);

            huidigeBlok = {
                start: startLokaleTijd,
                prijzen: [prijs],
                laatsteIndex: i
            };
        } else {
            huidigeBlok.prijzen.push(prijs);
            huidigeBlok.laatsteIndex = i;
        }
    }

    // Als we in een blok zaten, maar de prijs stijgt erboven (of de lijst is ten einde)
    if (inBlok && (prijs >= drempel || i === timestamps.length - 1)) {
        let eindTimestamp = timestamps[huidigeBlok.laatsteIndex] + 900;
        let eindDatum = new Date(eindTimestamp * 1000);
        let offset = eindDatum.getTimezoneOffset() * 60000;
        let eindLokaleTijd = new Date(eindDatum.getTime() - offset).toISOString().substring(11, 16);

        huidigeBlok.eind = eindLokaleTijd;

        // Bereken alleen de laagste prijs (gemiddelde is weggehaald!)
        let minPrijs = Math.min(...huidigeBlok.prijzen);
        huidigeBlok.min = minPrijs.toFixed(2);

        blokken.push(huidigeBlok);
        inBlok = false;
    }
}

// -----------------------------------------------------------------
// HET BERICHT OPBOUWEN
// -----------------------------------------------------------------
// De datum staat nu netjes in de titel!
let bericht = "📅 <b>De EPEX Prijzen Voor morgen (" + weergaveDatum + ")</b>\n\n";

if (blokken.length > 0) {
    // Het "<" teken is vervangen door tekst, zodat Error 400 wegblijft!
    bericht += "Hier zijn de voordeligste momenten (onder de € " + drempel + "):\n\n";

    for (let blok of blokken) {
        bericht += "⏱️ <b>" + blok.start + " - " + blok.eind + "</b>\n";
        bericht += "   Laagste prijs: € " + blok.min + " / MWh\n\n";
    }
} else {
    let absoluteMin = Math.min(...prijzen).toFixed(2);
    bericht += "Helaas, er zijn morgen géén prijzen onder de € " + drempel + " / MWh.\n\n";
    bericht += "📉 De laagste prijs morgen is € " + absoluteMin + " / MWh.";
}

// Stuur het bericht naar Telegram
msg.payload = {
    chatId: mijnChatId,
    type: "message",
    content: bericht,
    options: { parse_mode: "HTML" } 
};

return msg;

// Pak de datum en tijd van nú
let datum = new Date();

// Tel er precies 1 dag (morgen) bij op
datum.setDate(datum.getDate() + 1);

// Haal het jaartal, de maand en de dag eruit (en zorg voor een voorloopnul, bijv. '03')
let jaar = datum.getFullYear();
let maand = String(datum.getMonth() + 1).padStart(2, '0');
let dag = String(datum.getDate()).padStart(2, '0');

// Plak ze aan elkaar tot YYYY-MM-DD (bijv. 2026-03-07)
let morgenString = jaar + "-" + maand + "-" + dag;

// Maak de nieuwe URL en stop die in msg.url
// (Let op: Energy-Charts gebruikt vaak 'start' en 'end' tegelijk om het netjes af te bakenen voor 1 dag)
msg.url = "https://api.energy-charts.info/price?bzn=BE&start=" + morgenString + "&end=" + morgenString;

// Extraatje: stuur de datum ook door in een ander vakje, handig voor straks!
msg.datumMorgen = morgenString;

return msg;

// We krijgen een lijst (array) met resultaten terug
let records = msg.payload.results;

if (!records || records.length === 0) {
    return null;
}

// We maken een lijst met SQL commando's (één voor elk record)
let sqlQueries = [];

for (let i = 0; i < records.length; i++) {
    let item = records[i];

    // Tijd omzetten van UTC (Elia) naar Lokale tijd
    let datum = new Date(item.datetime);
    let offset = datum.getTimezoneOffset() * 60000;
    let lokaleTijd = new Date(datum.getTime() - offset);

    // Formatteer naar YYYY-MM-DD HH:MM:00
    let tijdstipStr = lokaleTijd.toISOString().replace('T', ' ').substring(0, 19);
    let prijs = item.imbalanceprice;

    // Voeg toe aan de lijst met queries
    if (prijs !== null && prijs !== undefined) {
        sqlQueries.push("('" + tijdstipStr + "', " + prijs + ")");
    }
}

// We voegen alles samen in één krachtige INSERT opdracht
if (sqlQueries.length > 0) {
    msg.topic = "INSERT OR REPLACE INTO onbalans_prijzen (tijdstip, prijs) VALUES " + sqlQueries.join(",");
    return msg;
}

return null;

// 1. Check of de API deprecated is (zit in de msg.payload van de bestaande aanroep)
const isDeprecated = msg.payload.deprecated;

// 2. Haal de status op uit het interne geheugen (context)
let status = context.get("waarschuwingStatus") || { firstSeen: null, lastMonthNotified: null };

if (isDeprecated === true) {
    let nu = new Date();

    // EERSTE KEER: Alarm slaan!
    if (!status.firstSeen) {
        status.firstSeen = nu.toISOString();
        status.lastMonthNotified = 6;
        context.set("waarschuwingStatus", status);

        msg.payload = {
            chatId: env.get("TELEGRAM_CHAT_ID"),
            type: "message",
            content: "🚨 <b>GROOT ALARM: API GAAT STOPPEN</b> 🚨\n\nFraunhofer heeft aangekondigd dat deze API over 6 maanden stopt. Tijd om een alternatief te zoeken!"
        };
        return msg;
    }

    // AFTELLEN:
    let startDatum = new Date(status.firstSeen);
    let eindDatum = new Date(startDatum);
    eindDatum.setMonth(eindDatum.getMonth() + 6);

    let maandenOver = Math.max(0, (eindDatum.getFullYear() - nu.getFullYear()) * 12 + (eindDatum.getMonth() - nu.getMonth()));

    // Alleen bericht als de maand verspringt
    if (maandenOver < status.lastMonthNotified) {
        status.lastMonthNotified = maandenOver;
        context.set("waarschuwingStatus", status);

        msg.payload = {
            chatId: env.get("TELEGRAM_CHAT_ID"),
            type: "message",
            content: "⏳ <b>API AFTELLING UPDATE</b>\n\nDe energie-API stopt over " + maandenOver + " maanden.\nDeadline: " + eindDatum.toLocaleDateString('nl-BE')
        };
        return msg;
    }
}

// Alles is ok? Dan sturen we niets door naar Telegram.
return null;
